CANCERS = ['Acute myeloid leukemia', 'Adrenal tumor', 'Anal sac adenocarcinoma (AGASACA)', 'B-cell lymphoma', 'Brain tumor / glioma', 'Cancer — any type', 'Cutaneous epitheliotropic lymphoma', 'Feline injection-site sarcoma', 'Feline mammary carcinoma', 'Hemangiosarcoma', 'Hepatocellular carcinoma', 'Histiocytic sarcoma', 'Insulinoma', 'Lymphoma — other', 'Mammary carcinoma', 'Mammary tumor — other', 'Mast cell tumor', 'Melanoma — other', 'Oral melanoma', 'Oral squamous cell carcinoma', 'Osteosarcoma', 'Other bone tumor', 'Other liver tumor', 'Other sarcoma', 'Other solid tumor', 'Primary lung tumor', 'Prostate cancer', 'Renal tumor', 'Sinonasal carcinoma', 'Soft tissue sarcoma', 'Spindle cell sarcoma', 'Squamous cell carcinoma', 'Squamous cell carcinoma — other', 'T-cell lymphoma', 'Thyroid carcinoma', 'Thyroid tumor / carcinoma', 'Urothelial / transitional cell carcinoma', 'Urothelial carcinoma', 'Pancreatic carcinoma', 'Intestinal carcinoma', 'Gallbladder carcinoma', 'Oral tumor — other', 'Ocular melanoma / iris melanocytic tumor', 'Other / not sure']
